using System.Text.Json;
using Microsoft.Xna.Framework;
namespace BluewaterHaul;
public static class Verification {
 public static void Run(){
  var root=Path.Combine(AppContext.BaseDirectory,"Data");var w=WorldData.Load(Path.Combine(root,"world.json"));var landmarks=JsonSerializer.Deserialize<List<Landmark>>(File.ReadAllText(Path.Combine(root,"landmarks.json")),WorldData.Options)!;var jobs=JsonSerializer.Deserialize<List<Delivery>>(File.ReadAllText(Path.Combine(root,"jobs.json")),WorldData.Options)!;int checks=0;
  void Check(bool condition,string message){checks++;if(!condition)throw new InvalidDataException(message);}
  Check(w.Buildings.Count>10000,"Missing map buildings");Check(w.Roads.Count>7000,"Missing road geometry");Check(w.Pois.Any(p=>p.Name=="Sarnia City Hall"),"Missing Sarnia City Hall");Check(w.Pois.Any(p=>p.Name=="Canatara Park"),"Missing Canatara Park");
  foreach(var r in w.Roads){Check(r.Points.Count>=2,"Road too short");foreach(var p in r.Points)Check(float.IsFinite(p[0])&&float.IsFinite(p[1])&&p[0]>=w.Bounds[0]-.1f&&p[0]<=w.Bounds[2]+.1f&&p[1]>=w.Bounds[1]-.1f&&p[1]<=w.Bounds[3]+.1f,"Unbounded road");}
  int roofIssues=0;foreach(var b in w.Buildings){Check(b.Points.Count>=3,"Invalid building");Check(b.Height>=3&&b.Height<=70,"Invalid generated height");var tris=Geo.Triangulate(b.Points);double polygon=0,triangles=0;for(int i=0;i<b.Points.Count;i++){var a=Geo.V(b.Points[i]);var c=Geo.V(b.Points[(i+1)%b.Points.Count]);polygon+=(double)a.X*c.Y-(double)c.X*a.Y;}polygon=Math.Abs(polygon)/2;
   for(int i=0;i<tris.Count;i+=3){var a=Geo.V(b.Points[tris[i]]);var c=Geo.V(b.Points[tris[i+1]])-a;var d=Geo.V(b.Points[tris[i+2]])-a;triangles+=Math.Abs((double)c.X*d.Y-(double)c.Y*d.X)/2;}
   if(b.RoofTriangles.Count>0){triangles=0;foreach(var t in b.RoofTriangles){var a=Geo.V(t[0]);var c=Geo.V(t[1])-a;var d=Geo.V(t[2])-a;triangles+=Math.Abs((double)c.X*d.Y-(double)c.Y*d.X)/2;}}
   if(Math.Abs(polygon-triangles)>Math.Max(2,polygon*.005))roofIssues++;
  }
  Check(roofIssues==0,"Roof triangulation incomplete for "+roofIssues+" buildings");
  Check(w.Areas.Any(a=>a.Name=="Lake Huron"&&a.Triangles.Count>0),"Lake Huron surface missing");Check(w.Areas.Any(a=>a.Name=="Saint Clair River"&&a.Triangles.Count>0),"River surface missing");
  foreach(var a in w.Areas.Where(a=>a.Name=="Lake Huron"||a.Name=="Saint Clair River")){int submerged=w.Buildings.Count(b=>Geo.Contains(a.Points,Geo.V(b.Center))&&!a.Holes.Any(h=>Geo.Contains(h,Geo.V(b.Center))));Check(submerged==0,"Main water surface overlaps "+submerged+" mapped buildings");}
  foreach(var lm in landmarks)Check(lm.Point.Length==2&&lm.Source.StartsWith("https://"),"Landmark lacks point/source");
  foreach(var j in jobs){Check(j.Pay>0&&j.Point.Length==2,"Invalid delivery");Check(!w.Buildings.Any(b=>Geo.Contains(b.Points,Geo.V(j.Point))),"Delivery inside a solid building");}
  var save=new SaveState{InteriorId=w.Buildings[0].Id,TruckX=100,TruckZ=200};save.Visits[save.InteriorId]=3;save.Collected.Add(save.InteriorId);save.Completed.Add(2);var recovered=JsonSerializer.Deserialize<SaveState>(JsonSerializer.Serialize(save,WorldData.Options),WorldData.Options)!;
  Check(recovered.Visits[save.InteriorId]==3&&recovered.Collected.Contains(save.InteriorId)&&recovered.Completed.Contains(2)&&recovered.TruckX==100&&recovered.TruckZ==200,"Save state round trip lost progress");
  var roads=new[]{new Road{Name="Main",Points=[[0,0],[100,0],[200,0]],Oneway="yes"},new Road{Name="Side",Points=[[100,0],[100,100]]}};
  var router=new RoadRouter(roads);var forward=router.Route(new(20,0),new(180,0));Check(forward.Count>=2&&forward[0]==new Vector2(20,0)&&forward[^1]==new Vector2(180,0),"Route endpoint snapping failed");
  Check(router.Route(new(180,0),new(20,0)).Count==0,"Route ignored one-way restriction");Check(new RoadRouter(roads,true).Route(new(180,0),new(20,0)).Count>=2,"Walking reverse route failed");Check(router.Route(new(20,0),new(100,80)).Any(p=>p==new Vector2(100,0)),"Route skipped junction");
  var camera=new MapCamera{Center=new(500,700),Scale=.5f};var rect=new Rectangle(20,30,900,600);var anchor=new Vector2(230,310);var before=camera.World(anchor,rect);camera.Zoom(anchor,rect,2,.01f);Check(Vector2.Distance(before,camera.World(anchor,rect))<.001f,"Zoom anchor moved");Check(Vector2.Distance(camera.World(camera.Screen(before,rect),rect),before)<.001f,"Map coordinate round trip failed");
  save.Waypoint=[123,456];save.WaypointName="Navigation test";recovered=JsonSerializer.Deserialize<SaveState>(JsonSerializer.Serialize(save,WorldData.Options),WorldData.Options)!;Check(recovered.Waypoint![1]==456&&recovered.WaypointName==save.WaypointName,"Waypoint save round trip failed");
  Check(w.Areas.Count(a=>a.Kind=="parking")>=300,"Parking surfaces missing from supplied extract");
  var taggedHeights=w.Buildings.Where(b=>b.HeightKnown).ToDictionary(b=>b.Id,b=>b.Height);PlaceIdentity.Prepare(w);Check(w.Buildings.Select(b=>b.Style).Distinct().Count()>=8,"Architecture styles not differentiated");Check(taggedHeights.All(p=>w.Buildings.First(b=>b.Id==p.Key).Height==p.Value),"Source height was overwritten");
  var localRouter=new RoadRouter(w.Roads);foreach(var b in w.Buildings){var near=localRouter.Snap(Geo.V(b.Center)).Point;b.Door=b.Points.Select((p,i)=>Geo.Nearest(near,Geo.V(p),Geo.V(b.Points[(i+1)%b.Points.Count]))).MinBy(p=>Vector2.DistanceSquared(p,near));}
  foreach(var b in w.Buildings.Where(b=>b.Landmark.Length>0)){var mesh=new MeshBuilder();Architecture.Building(mesh,b);Check(mesh.Vertices.Count>0&&mesh.Vertices.All(v=>float.IsFinite(v.Position.X)&&float.IsFinite(v.Position.Y)&&float.IsFinite(v.Position.Z)),"Invalid landmark geometry: "+b.Landmark);}
  Check(w.Buildings.Any(b=>b.Landmark=="cityhall")&&w.Buildings.Any(b=>b.Landmark=="library")&&w.Buildings.Any(b=>b.Landmark=="lawrence"),"Core landmark treatments missing");
  foreach(var mesh in StreetScene.Build(w))Check(mesh.Vertices.All(v=>float.IsFinite(v.Position.X)&&float.IsFinite(v.Position.Y)&&float.IsFinite(v.Position.Z)),"Invalid street geometry");Check(StreetScene.Signs.Any(s=>s.Kind=="street")&&StreetScene.Signs.Any(s=>s.Kind=="building"),"World signs missing");Check(StreetScene.SidewalkPieces>1000&&StreetScene.ParkingBays>100&&StreetScene.BridgeMembers>100,"Street/bridge detail missing");
  Check(PlaceIdentity.District(new(-5900,-1500))=="POINT EDWARD"&&PlaceIdentity.District(new(-4274,1547))=="MITTON VILLAGE","District identities failed");
  foreach(var kind in new[]{"car","pickup","van","bus","truck"}){var spec=VehicleSpec.For(kind);float velocity=0;for(int i=0;i<600;i++)velocity=VehiclePhysics.IntegrateSpeed(velocity,1,false,false,true,1f/60,spec,false);Check(velocity>10&&velocity<=spec.MaxSpeed,"Acceleration/cap: "+kind);for(int i=0;i<400;i++)velocity=VehiclePhysics.IntegrateSpeed(velocity,0,true,false,true,1f/60,spec,false);Check(velocity==0,"Braking: "+kind);for(int i=0;i<300;i++)velocity=VehiclePhysics.IntegrateSpeed(velocity,-1,false,false,true,1f/60,spec,false);Check(velocity<0&&velocity>=-spec.Reverse,"Reverse: "+kind);Check(VehiclePhysics.TurnRate(-5,.2f,spec)<0&&VehiclePhysics.TurnRate(5,.2f,spec)>0,"Reverse steering: "+kind);Check(VehiclePhysics.IntegrateSpeed(0,1,false,false,false,.1f,spec,false)==0,"Empty tank: "+kind);Check(VehicleModels.Make(new(){Kind=kind}).Vertices.All(v=>float.IsFinite(v.Position.X)),"Vehicle mesh: "+kind);}
  var sedan=VehicleSpec.For("car");Check(VehiclePhysics.Overlap(Vector2.Zero,0,sedan,new(1,0),.7f,sedan),"Vehicle contact missed");Check(!VehiclePhysics.Overlap(Vector2.Zero,0,sedan,new(8,0),.7f,sedan),"Separated vehicles collide");
  save.Vehicles=[new(){Id=7,Kind="pickup",X=123,Z=456,Yaw=.75f,Fuel=42}];save.ActiveVehicle=7;save.ThirdPerson=false;recovered=JsonSerializer.Deserialize<SaveState>(JsonSerializer.Serialize(save,WorldData.Options),WorldData.Options)!;Check(recovered.Vehicles[0].Point==new Vector2(123,456)&&recovered.Vehicles[0].Fuel==42&&recovered.ActiveVehicle==7&&!recovered.ThirdPerson,"Vehicle coordinates/fuel/camera save failed");Check(JsonSerializer.Deserialize<SaveState>("{\"TruckX\":123}",WorldData.Options)!.Vehicles.Count==0,"Legacy save migration defaults failed");
  for(int second=0;second<120;second++){Check(!(CityRules.Signal(second,true)==2&&CityRules.Signal(second,false)==2),"Conflicting signal greens");Check(CityRules.Signal(second,true)==CityRules.Signal(second+60,true),"Signal period drift");}Check(CityRules.Signal(26,true)==1&&CityRules.Signal(29,true)==0&&CityRules.Signal(30,false)==2,"Signal amber/clearance phases");Check(CityRules.Routine(22)=="Home"&&CityRules.Routine(8)=="Commute"&&CityRules.Routine(10)=="Work"&&CityRules.Routine(13)=="Lunch"&&CityRules.Routine(18)=="Errands","Citizen daily schedule");
  Check(TroubleRules.Stars(0)==0&&TroubleRules.Stars(32)==2&&TroubleRules.Stars(90)==3,"Wanted tiers failed");Check(TroubleRules.Damage(1)==0&&TroubleRules.Damage(12)>0&&TroubleRules.Damage(100)<=60,"Impact damage bounds failed");save.Trouble=new(){Heat=62,Escape=12,Fines=250,ReportDelay=2};save.Trouble.Stolen.Add(7);save.Trouble.PropertyDamage[123]=45;save.Vehicles[0].Damage=20;recovered=JsonSerializer.Deserialize<SaveState>(JsonSerializer.Serialize(save,WorldData.Options),WorldData.Options)!;Check(recovered.Trouble.Heat==62&&recovered.Trouble.Stolen.Contains(7)&&recovered.Trouble.PropertyDamage[123]==45&&recovered.Vehicles[0].Damage==20&&recovered.Trouble.ReportDelay==2,"Trouble save round trip failed");
  Check(CrashRules.Bounce(new(10,0),new(-1,0)).X<0,"Wall rebound failed");Check(CrashRules.Bounce(new(10,0),new(0,1))==new Vector2(10,0),"Tangential velocity changed");float impulse=CrashRules.Impulse(new(10,0),Vector2.Zero,new(-1,0),1400,1400);Check(impulse>0&&10-impulse/1400<impulse/1400,"Car impulse transfer failed");Check(CrashRules.Mass("bus")>CrashRules.Mass("car"),"Vehicle mass classes failed");save.Vehicles[0].Destroyed=true;save.Vehicles[0].BurnTime=8;recovered=JsonSerializer.Deserialize<SaveState>(JsonSerializer.Serialize(save,WorldData.Options),WorldData.Options)!;Check(recovered.Vehicles[0].Destroyed&&recovered.Vehicles[0].BurnTime==8,"Wreck save failed");
  Console.WriteLine($"Place pass: {StreetScene.SidewalkPieces:N0} sidewalk strips, {StreetScene.ParkingBays:N0} parking marks, {StreetScene.Signs.Count:N0} world signs; landmark geometry and source heights passed.");
  Console.WriteLine($"PASS: {checks:N0} checks; {w.Buildings.Count:N0} buildings, {w.Roads.Count:N0} roads, {w.Pois.Count:N0} named places, {landmarks.Count} researched markers, {jobs.Count} delivery destinations. Roof triangulation and persistence round trip passed.");
 }
}
